from common import *


if __name__ == "__main__":
    save_source(__file__)
    print("Sampling task process tree; summed RSS is not unique physical memory.", flush=True)
    while not (TMP / "stop-monitor").exists():
        output = subprocess.run(["ps", "-axo", "pid=,ppid=,rss=,%cpu=,etime=,command="], capture_output=True, text=True, check=True).stdout
        rows = {}
        for line in output.splitlines():
            fields = line.split(None, 5)
            if len(fields) != 6:
                continue
            pid, parent, rss, cpu, elapsed, command = fields
            rows[int(pid)] = {"pid": int(pid), "ppid": int(parent), "rss_KiB": int(rss), "cpu_percent": float(cpu), "elapsed": elapsed, "command": command}
        owned = {pid for pid, row in rows.items() if str(TMP) + "/" in row["command"] and "python" in row["command"] and " -c " not in row["command"]}
        while True:
            descendants = {pid for pid, row in rows.items() if row["ppid"] in owned}
            new = descendants - owned
            if not new:
                break
            owned |= new
        sample = {"at": time.time(), "stage": read(PROGRESS).get("pipeline_stage"), "processes": [rows[pid] for pid in sorted(owned)], "sum_rss_KiB": sum(rows[pid]["rss_KiB"] for pid in owned), "rss_interpretation": "Summed resident sets may double-count shared pages; sample, not a guaranteed peak.", "system_swap": subprocess.run(["sysctl", "-n", "vm.swapusage"], capture_output=True, text=True).stdout.strip()}
        with (TMP / "process-tree-samples.jsonl").open("a") as handle:
            handle.write(json.dumps(sample, ensure_ascii=False) + "\n")
        time.sleep(50)
    print("Resource sampling stopped.", flush=True)
